import { useState, useEffect, useRef } from "react";
import { useLocation } from "wouter";
import { motion, AnimatePresence } from "framer-motion";
import { ArrowLeft, Search, Clock, Activity, Loader2, ChevronRight, Stethoscope, AlertTriangle, Home, Pill, Eye, RefreshCw, ClipboardList, TestTube, Ban, UtensilsCrossed, Plus, MessageCircle, Send, UserRound } from "lucide-react";
import type { User as UserType } from "@shared/schema";
import { api } from "@shared/routes";

const getStoredUser = () => {
  const stored = localStorage.getItem("med_user");
  return stored ? JSON.parse(stored) as UserType : null;
};

type CheckStep = "symptom" | "related" | "onset" | "severity" | "loading" | "results";
type ChatMessage = { role: "user" | "assistant"; text: string };

const ONSET_OPTIONS = [
  { label: "Today", value: "today" },
  { label: "2-3 days ago", value: "2-3 days ago" },
