const RESULT_TABS = [
  { id: "overview", label: "Overview" },
  { id: "actions", label: "Actions" },
  { id: "worry", label: "When to Worry" },
  { id: "doctor", label: "Doctor Prep" },
  { id: "chat", label: "Chat" },
];

const SECTION_MAP: Record<string, string[]> = {
  overview: [
    "What could this be?",
    "Should I be worried?",
    "How urgent is this?",
  ],
  actions: [
    "What can I do right now at home?",
